(function(){
  CardSpoke_MODS.register('flow-mapper', {
    meta: {
      name: 'Flow Mapper',
      type: 'Mod',
      version: '1.0.0',
      creator: 'CardSpoke Team',
      description: 'Adds navigational breadcrumbs when traversing deep stacks',
      releaseDate: '2024-10-20',
      source: 'official'
    },
    onNavigate(ctx, stack){
      if(!Array.isArray(stack)) return;
      const crumb = document.createElement('div');
      crumb.className = 'fm-crumbs';
      crumb.textContent = 'Trail: ' + stack.map(item => item.title || item.id).join(' / ');
      const existing = document.querySelector('.fm-crumbs');
      if(existing) existing.remove();
      document.body.appendChild(crumb);
    },
    onDisable(){
      const existing = document.querySelector('.fm-crumbs');
      if(existing) existing.remove();
    }
  });
})();
